function a79Allocate(total,weights){const sum=weights.reduce(function(a,b){return a+b;},0);let left=total;return weights.map(function(w,i){const v=i===weights.length-1?left:Math.round(total*w/sum);left-=v;return v;});}

function a79MonthTotals(year,month){const factor=year===2026?1:year===2025?.93:.81;let expense=Math.round(expenseMonths[month-1]*factor),income=year===2026?1200000:year===2025?1080000:950000;if(year===2026&&[8,9,10].includes(month)){expense=state.ledger==='日常生活'?({8:389525,9:412500,10:328650}[month]):680080;income=state.ledger==='日常生活'?1200000:2400000;}for(const row of state.additions.filter(r=>r.ledger===state.ledger&&(r.year||2026)===year&&r.month===month)){if(row.type==='expense')expense+=Math.round(row.amount*100);if(row.type==='income')income+=Math.round(row.amount*100);}return {expense,income};}

function a79GetData(){
 let entries=[];
 if(a79State.scope==='month'){
  const days=a79State.year===a79Now.year&&a79State.month===a79Now.month?a79Now.day:new Date(a79State.year,a79State.month,0).getDate();
  const totals=a79MonthTotals(a79State.year,a79State.month),expenses=a79Allocate(totals.expense,rawDays.slice(0,days));
  const incomeWeights=Array.from({length:days},function(_,i){return i===0?55:i===4?6:i===11?4:i===days-1?55:0;});
  const incomes=a79Allocate(totals.income,incomeWeights);
  entries=expenses.map(function(v,i){return {expense:v,income:incomes[i],label:a79State.month+'.'+String(i+1).padStart(2,'0'),full:a79State.month+'月'+(i+1)+'日',unit:'天'};});
 }else if(a79State.scope==='year'){
  const months=a79State.year===a79Now.year?a79Now.month:12;
  entries=Array.from({length:months},function(_,i){return Object.assign(a79MonthTotals(a79State.year,i+1),{label:(i+1)+'月',full:a79State.year+'年'+(i+1)+'月',unit:'个月'});});
 }else{
  entries=[2024,2025,2026].map(function(y){let expense=0,income=0;const months=y===a79Now.year?a79Now.month:12;for(let m=1;m<=months;m++){const t=a79MonthTotals(y,m);expense+=t.expense;income+=t.income;}return {expense:expense,income:income,label:String(y),full:y+'年',unit:'年'};});
 }
 if(a79State.mode==='empty')entries=entries.map(function(e){return Object.assign({},e,{expense:0,income:0});});
 entries.forEach(function(e){e.balance=e.income-e.expense;e.value=e[a79State.metric];});
 const expense=entries.reduce(function(a,e){return a+e.expense;},0),income=entries.reduce(function(a,e){return a+e.income;},0),total=a79State.metric==='balance'?income-expense:a79State.metric==='expense'?expense:income;
 const baseCount=a79State.metric==='income'?4:a79State.metric==='balance'?30:26;
 const count=a79State.mode==='empty'?0:a79State.scope==='month'?baseCount:a79State.scope==='year'?baseCount*entries.length:baseCount*30;
 return {entries:entries,total:total,expense:expense,income:income,count:count,average:entries.length?total/entries.length:0,averageLabel:a79State.scope==='month'?'日均':a79State.scope==='year'?'月均':'年均',averageUnit:a79State.scope==='month'?'天':a79State.scope==='year'?'个月':'年',a79Empty:total===0&&expense===0&&income===0};
}

