 const label=a79Model.averageLabel+' '+(a79Model.average<0?'−':'')+'¥'+a79Money(Math.abs(a79Model.average)),labelWidth=Math.min(112,54+label.length*2.5),labelY=Math.max(5,Math.min(averageY-8,139));
 content+='<line class="mean-line" x1="1" y1="'+averageY+'" x2="299" y2="'+averageY+'"/><line class="mean-hit" x1="1" y1="'+averageY+'" x2="299" y2="'+averageY+'" data-action="average"/><g role="button" tabindex="0" data-action="average" aria-label="平均线 '+esc(label)+'，查看计算口径"><rect class="mean-bg" x="'+(300-labelWidth)+'" y="'+(labelY-9)+'" width="'+labelWidth+'" height="16" rx="4"/><text class="mean-text" x="297" y="'+(labelY+2)+'" text-anchor="end">'+esc(label)+'</text></g></svg>';
 if(a79State.selectedBar>=0){const e=a79Model.entries[a79State.selectedBar],left=Math.max(56,Math.min(244,(a79State.selectedBar+.5)*spacing));content+='<div class="chart-tip" style="left:'+left/3+'%;transform:translateX(-50%)" role="status">'+esc(e.full)+'<strong>'+a79Labels[a79State.metric]+' '+(e.value<0?'−':'')+'¥'+a79Money(Math.abs(e.value))+'</strong></div>';}
