function a79Trend(){const e=a79Model.entries,n=e.length,positions=[0,Math.floor((n-1)/2),n-1],atLatest=a79State.year===a79Now.year&&(a79State.scope==='year'||a79State.month===a79Now.month);return '<section class="card trend-card" aria-label="'+a79Labels[a79State.metric]+'趋势"><div class="card-head"><h3>'+a79Labels[a79State.metric]+'趋势</h3><span class="unit">单位：元</span></div><div class="chart-wrap">'+a79SvgChart()+'</div><div class="chart-labels">'+positions.map(function(i){return '<span>'+e[i].label+'</span>';}).join('')+'</div><div class="chart-footer">'+(a79State.scope==='all'?'<span>点柱形查看年度金额</span>':'<button type="button" class="period-step" data-move="-1" aria-label="上个统计周期">'+a79Icon('left')+(a79State.scope==='year'?'上年':'上月')+'</button><span>'+(a79State.selectedBar>=0?'再点一次可取消选择':'点柱形，查看'+(a79State.scope==='month'?'当天':'当月')+'收支')+'</span><button type="button" class="period-step" data-move="1" '+(atLatest?'disabled':'')+' aria-label="下个统计周期">'+(a79State.scope==='year'?'下年':'下月')+a79Icon('chevron')+'</button>')+'</div></section>';}

function a79ShareCard(){const cats=a79Categories(),other={name:'其他分类',percentage:cats.slice(3).reduce(function(a,c){return a+c.percentage;},0),index:-1},selected=a79State.category===-1?other:cats[a79State.category]||cats[0],items=cats.slice(0,3);if(cats.length>3)items.push(other);const percent=selected.percentage;return '<section class="card proportion-card" aria-label="分类占比"><div class="card-head"><h3>分类占比</h3><button type="button" class="quiet-link" data-action="manage-categories">管理分类'+a79Icon('chevron')+'</button></div><div class="share-layout"><div class="donut" role="img" aria-label="'+esc(selected.name+'占总'+a79Labels[a79State.metric]+percent.toFixed(1)+'%')+'"><svg viewBox="0 0 132 132"><circle class="track" cx="66" cy="66" r="52"/><circle class="slice" cx="66" cy="66" r="52" pathLength="100" stroke-dasharray="'+percent+' '+(100-percent)+'"/></svg><div class="donut-center"><small>'+esc(selected.name)+'</small><strong class="num">'+percent.toFixed(1)+'<span style="font-size:11px;margin-left:1px">%</span></strong></div></div><div class="share-legend">'+items.map(function(c){return '<button type="button" class="legend-choice" data-category="'+c.index+'" aria-pressed="'+(a79State.category===c.index)+'"><span class="legend-name"><i class="legend-mark"></i>'+esc(c.name)+'</span><span class="num">'+c.percentage.toFixed(1)+'%</span></button>';}).join('')+'</div></div><p class="share-caption">点选分类，查看它在总'+a79Labels[a79State.metric]+'中的占比</p></section>';}

function a79Ranking(){const cats=a79Categories(),shown=a79State.showAll?cats:cats.slice(0,4),list=shown.map(function(c){const open=a79State.expanded.has(c.index),children=a79Allocate(c.amount,c.children.map(function(s){return s.weight;}));return '<div class="rank-item"><div class="rank-main"><button type="button" data-detail="'+c.index+'" aria-label="'+esc(c.name)+'分类详情">'+a79CategoryIcon(c)+'</button><button type="button" class="rank-link" data-detail="'+c.index+'" aria-label="查看'+esc(c.name)+'分类详情"><span class="rank-title"><span class="rank-name">'+esc(c.name)+'</span><span class="rank-amount num">'+a79Money(c.amount)+'</span></span><span class="rank-bar-track" style="display:block"><span class="rank-bar" style="display:block;width:'+c.percentage+'%"></span></span></button><div class="rank-tail"><div class="rank-percentage num">'+c.percentage.toFixed(1)+'%</div>'+(c.children.length?'<button type="button" class="expand-button" data-expand="'+c.index+'" aria-expanded="'+open+'" aria-label="'+(open?'收起':'展开')+esc(c.name)+'二级分类">'+a79Icon('down')+'</button>':'<button type="button" class="expand-button" data-detail="'+c.index+'" aria-label="'+esc(c.name)+'分类详情">'+a79Icon('chevron')+'</button>')+'</div></div>'+(open?'<div class="children">'+c.children.map(function(s,i){return '<button type="button" class="child-row" data-detail="'+c.index+':'+i+'" aria-label="查看'+esc(s.name)+'分类详情">'+a79CategoryIcon(s)+'<span class="child-name">'+esc(s.name)+'</span><span class="num">'+a79Money(children[i])+'</span>'+a79Icon('chevron')+'</button>';}).join('')+'</div>':'')+'</div>';}).join('');return '<section class="card ranking-card" aria-label="分类排行"><div class="card-head"><h3>分类排行</h3><span class="unit">按金额排序</span></div><div class="ranking-list">'+list+'</div>'+(cats.length>4?'<button type="button" class="more-categories" data-action="more-categories">'+(a79State.showAll?'收起分类':'全部 '+cats.length+' 个分类')+a79Icon(a79State.showAll?'down':'chevron')+'</button>':'')+'</section>';}

function a79BalanceCard(){return '<section class="card" aria-label="收支构成"><div class="card-head"><h3>收支构成</h3><span class="unit">结余 = 收入 − 支出</span></div><div class="balance-composition"><div class="composition-cell"><small>本期收入</small><strong class="num">¥'+a79Money(a79Model.income)+'</strong></div><div class="composition-cell"><small>本期支出</small><strong class="num">¥'+a79Money(a79Model.expense)+'</strong></div></div><div class="composition-links"><button type="button" data-metric="income">查看收入分类'+a79Icon('chevron')+'</button><button type="button" data-metric="expense">查看支出分类'+a79Icon('chevron')+'</button></div></section>';}

function a79Empty(){return '<section class="card empty-card"><div class="empty-mark">'+a79Icon('chart')+'</div><h3>这个'+(a79State.scope==='month'?'月':a79State.scope==='year'?'年度':'账本')+'还没有'+a79Labels[a79State.metric]+'记录</h3><p>换个统计周期看看，<br>或者切换到其他收支视角。</p><button type="button" class="soft-button" data-metric="'+(a79State.metric==='expense'?'income':'expense')+'">查看'+(a79State.metric==='expense'?'收入':'支出')+'</button></section>';}

function a79Skeleton(){return '<section class="card skeleton-card" aria-label="统计加载中" role="status"><div class="skeleton skeleton-title"></div><div class="skeleton skeleton-total"></div><div class="skeleton skeleton-row"></div></section><section class="card"><div class="skeleton skeleton-title"></div><div class="skeleton skeleton-chart"></div></section>';}
  function a79Markup(html){return html.replace(/class="([^"]*)"/g,(_,names)=>'class="'+names.split(/\s+/).map(name=>name.startsWith('a79-')?name:'a79-'+name).join(' ')+'"').replace(/data-action="([^"]+)"/g,(_,name)=>'data-action="a79-'+name+'"');}
  function a79Page(){a79Model=a79GetData();let body='';if(state.a79Mode==='loading')body=a79Skeleton();else if(state.a79Mode==='error')body='<section class="card empty-card"><div class="empty-mark">'+a79Icon('refresh')+'</div><h3>暂时没能读到账本</h3><p>账单仍然保留，稍后再试一次。</p><button type="button" class="soft-button" data-action="retry">重新加载</button></section>';else{if(state.a79Mode==='foreign')body+='<div class="notice">'+a79Icon('globe')+'<span>有 2 笔外币账单尚未折算</span><button type="button" data-action="recalc">补折算</button></div>';body+=a79Summary();if(state.a79Mode==='foreign')body+='<p class="conversion-note">统计金额已按账单历史汇率折算为 CNY</p>';body+=a79Model.empty?a79Empty():a79Trend()+(state.report==='balance'?a79BalanceCard():a79ShareCard()+a79Ranking());body+='<section class="card resource-card"><button class="resource-row" data-action="annual">'+a79Icon('chart')+'<span><strong>年度账单</strong><small>回顾这一年的小日常</small></span>'+a79Icon('chevron','chevron')+'</button><button class="resource-row" data-action="share">'+a79Icon('image')+'<span><strong>生成分享海报</strong><small>记录生活，也分享生活</small></span>'+a79Icon('chevron','chevron')+'</button></section>';}
    return '<div class="a79-shell" data-approved-insights="A1"><div class="a79-app-head"><h2>洞察</h2><div class="a79-header-actions">'+btn('page:ai',a79Icon('sparkles')+'<span>AI</span>','蜜蜂 AI','a79-ai-button')+btn('a79-share',a79Icon('share'),'分享统计','a79-icon-button')+'</div></div><div class="a79-scope-wrap"><div class="a79-scope-tabs" role="tablist" aria-label="统计周期">'+[['month','月'],['year','年'],['all','全部']].map(([key,name])=>btn('a79-scope:'+key,name,name+'统计','',`role="tab" aria-selected="${state.period===key}" aria-pressed="${state.period===key}"`)).join('')+'</div></div><div class="a79-feed a79-scroll">'+a79Markup(body)+'</div></div>';}
  report=function(){a79Prepare('report');return a79Page();};
  for(const[key,title]of a79Scenes)fDefine(key,title,'主要页面','main/analytics_page.dart',a79Page);
  const a79Render=fRender;fRender=function(key){if(a79Scenes.some(s=>s[0]===key)){a79Prepare(key);return a79Page();}return a79Render(key);};
  rSpecs['a79-average']={title:'平均值怎么算',host:'report',kind:'dialog'};
  rSpecs['a79-recalc']={title:'补齐外币折算',host:'report',kind:'dialog'};
  rSpecs['a79-period']={title:'选择周期',host:'report',kind:'sheet'};
  const a79PreviousModal=rModalBody;rModalBody=function(key){if(key==='a79-average'){const d=a79GetData();return '<div class="a79-formula"><span>¥'+a79Money(d.total)+'</span><span>÷</span><span>'+d.entries.length+' '+d.averageUnit+'</span><span>=</span><strong>¥'+a79Money(d.average)+'</strong></div><p>'+esc(a79PeriodLabel())+'已发生 '+d.entries.length+' '+d.averageUnit+'。没有记账的日期或月份也计入平均，未来日期和月份不计入。</p><p>图中虚线与上方汇总使用同一口径。结余为收入减支出，支持正值和负值。</p>'+btn('r-close','知道了','关闭平均值说明','bc-primary');}if(key==='a79-recalc')return '<p>使用有效汇率补齐 2 笔尚未折算的外币账单。原币金额和已有历史折算金额保持。</p><div class="j-picker-actions">'+btn('r-close','取消','取消补折算','bc-secondary')+btn('a79-confirm-recalc','补折算','确认补折算','bc-primary')+'</div>';if(key==='a79-period'){const d=jDraft('month');return jWheelGroup(jWheel('year',Array.from({length:27},(_,i)=>2000+i),d.year,'年','年份')+(state.period==='year'?'':jWheel('month',Array.from({length:d.year===2026?10:12},(_,i)=>i+1),d.month,'月','月份')))+'<div class="j-picker-actions">'+btn('r-close','取消','取消统计周期','bc-secondary')+btn('a79-confirm-period','确定','确认统计周期','bc-primary')+'</div>';}return a79PreviousModal(key);};
  function a79Move(delta){if(state.period==='all')return;if(state.period==='year')state.year=Math.min(a79Now.year,state.year+delta);else{const d=new Date(state.year,state.month-1+delta,1);if(d<=new Date(a79Now.year,a79Now.month-1,1)){state.year=d.getFullYear();state.month=d.getMonth()+1;}}a79ResetSelection();}
  function a79Refresh(keepScroll=false){const y=phone.querySelector('.a79-scroll')?.scrollTop||0;render();if(keepScroll){const feed=phone.querySelector('.a79-scroll');if(feed)feed.scrollTop=y;}persist();}
  root.addEventListener('click',event=>{const target=event.target.closest('button,g[data-bar],g[data-action],line[data-action]');if(!target)return;const inView=target.closest('.a79-shell'),action=target.dataset.action||'';if(!inView&&!action.startsWith('a79-'))return;const metric=target.dataset.metric,bar=target.dataset.bar,category=target.dataset.category,expand=target.dataset.expand,detail=target.dataset.detail,move=target.dataset.move;if(!action.startsWith('a79-')&&![metric,bar,category,expand,detail,move].some(x=>x!==undefined))return;event.preventDefault();event.stopImmediatePropagation();if(metric){state.report=metric;a79ResetSelection();a79Refresh();return;}if(bar!==undefined){const index=Number(bar);state.a79Selected=state.a79Selected===index?-1:index;a79Refresh(true);return;}if(category!==undefined){state.a79Category=Number(category);a79Refresh(true);return;}if(expand!==undefined){const index=Number(expand);a79Expanded.has(index)?a79Expanded.delete(index):a79Expanded.add(index);a79Refresh(true);return;}if(detail!==undefined){const [index,childIndex]=detail.split(':').map(Number),c=a79Categories()[index];dOpenCategory(c.name,Number.isFinite(childIndex)?c.children[childIndex].name:'',state.report);return;}if(move!==undefined){a79Move(Number(move));a79Refresh();return;}const[k,value]=action.split(':');if(k==='a79-scope'){state.period=value;a79ResetSelection();}else if(k==='a79-average'||k==='a79-recalc'){rOpenModal(k);return;}else if(k==='a79-period'){state.jWheel={kind:'month',year:state.year,month:state.month};rOpenModal(k);return;}else if(k==='a79-confirm-period'){for(const wheel of phone.querySelectorAll('[data-j-wheel]'))jWheelRead(wheel);state.year=state.jWheel.year;state.month=state.jWheel.month;rDismiss();a79ResetSelection();}else if(k==='a79-confirm-recalc'){rDismiss();state.a79Mode='ready';notice('设计预览：补折算完成');}else if(k==='a79-more-categories')state.a79ShowAll=!state.a79ShowAll;else if(k==='a79-manage-categories'){navigate('leaf','分类管理');return;}else if(k==='a79-annual'){navigate('annual');return;}else if(k==='a79-share'){sc100Open(state.period==='all'?'ledger':state.period);return;}else if(k==='a79-retry')state.a79Mode='ready';else return;a79Refresh();},true);
  root.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key)&&event.target.matches('.a79-shell g[data-bar],.a79-shell g[data-action]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});

  const a79Dismiss=rDismiss;rDismiss=function(){const feed=phone.querySelector('.a79-scroll'),y=feed?.scrollTop,context=[state.page,state.year,state.month,state.period,state.report].join('|');a79Dismiss();if(y!==undefined)requestAnimationFrame(()=>{if(context===[state.page,state.year,state.month,state.period,state.report].join('|')){const next=phone.querySelector('.a79-scroll');if(next)next.scrollTop=y;}});};
